// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import {
    createCollection,
    createLink,
    createHighlight,
    deleteHighlight,
    deleteCollection,
} from './skyrampUtils';

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Request Body
    const collectionsPostRequestBody: string = `{
        "color": "#0ea5e9",
        "description": "",
        "name": "Highlights Delete"
    }`;

    const collectionsPostResponse = await createCollection(client, headers, collectionsPostRequestBody);
    expect(collectionsPostResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(collectionsPostResponse, "response.name"), 'name').toBe("Highlights Delete");
    expect(getResponseValue(collectionsPostResponse, "response.color"), 'color').toBe("#0ea5e9");
    expect(getResponseValue(collectionsPostResponse, "response.id"), 'id').toBeGreaterThan(0);

    // Request Body
    const linksPostRequestBody: string = `{
        "collection": {
            "id": 6101
        },
        "description": "",
        "name": "Delete Source",
        "tags": [],
        "type": "url",
        "url": "https://example.com/delete"
    }`;

    const linksPostResponse = await createLink(
        client,
        headers,
        linksPostRequestBody,
        {"collection.id": getResponseValue(collectionsPostResponse, "response.id")}
    );
    expect(linksPostResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(linksPostResponse, "response.name"), 'name').toBe("Delete Source");
    expect(getResponseValue(linksPostResponse, "response.url"), 'url').toBe("https://example.com/delete");
    expect(getResponseValue(linksPostResponse, "response.collectionId"), 'collectionId').toBe(getResponseValue(collectionsPostResponse, "response.id"));
    expect(getResponseValue(linksPostResponse, "response.id"), 'id').toBeGreaterThan(0);

    // Request Body
    const highlightsPostRequestBody: string = `{
        "color": "blue",
        "endOffset": 14,
        "linkId": 6202,
        "startOffset": 0,
        "text": "Delete passage"
    }`;

    const highlightsPostResponse = await createHighlight(
        client,
        headers,
        highlightsPostRequestBody,
        {"linkId": getResponseValue(linksPostResponse, "response.id")}
    );
    expect(highlightsPostResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(highlightsPostResponse, "response.color"), 'color').toBe("blue");
    expect(getResponseValue(highlightsPostResponse, "response.text"), 'text').toBe("Delete passage");
    expect(getResponseValue(highlightsPostResponse, "response.startOffset"), 'startOffset').toBe(0);
    expect(getResponseValue(highlightsPostResponse, "response.endOffset"), 'endOffset').toBe(14);
    expect(getResponseValue(highlightsPostResponse, "response.linkId"), 'linkId').toBe(getResponseValue(linksPostResponse, "response.id"));
    expect(getResponseValue(highlightsPostResponse, "response.id"), 'id').toBeGreaterThan(0);

    const highlightsHighlightsDeleteResponse = await deleteHighlight(
        client,
        headers,
        getResponseValue(highlightsPostResponse, "response.id")
    );
    expect(highlightsHighlightsDeleteResponse.statusCode, 'status code').toBe(200);

    // Deleting your own existing highlight succeeds and reports the id it removed.
    expect(getResponseValue(highlightsHighlightsDeleteResponse, "response"), 'deleted highlight id').toBe(getResponseValue(highlightsPostResponse, "response.id"));

    const highlightsHighlightsDelete1Response = await deleteHighlight(
        client,
        headers,
        getResponseValue(highlightsPostResponse, "response.id"),
        403
    );
    expect(highlightsHighlightsDelete1Response.statusCode, 'status code').toBe(403);

    // The highlight is gone, so nothing may be reported as deleted a second time.
    expect(getResponseValue(highlightsHighlightsDelete1Response, "response"), 'nothing was deleted twice').not.toBe(getResponseValue(highlightsPostResponse, "response.id"));

    const highlights999999999DeleteResponse = await deleteHighlight(client, headers, "999999999", 403);
    expect(highlights999999999DeleteResponse.statusCode, 'status code').toBe(403);

    expect(getResponseValue(highlights999999999DeleteResponse, "response"), 'an id that never existed reports no deletion').not.toBe(999999999);

    const notANumberDeleteResponse = await deleteHighlight(client, headers, "not-a-number", 400);
    expect(notANumberDeleteResponse.statusCode, 'status code').toBe(400);

    expect(getResponseValue(notANumberDeleteResponse, "response"), 'a malformed id reports no deletion').not.toBe("not-a-number");

    const collectionsCollectionsDeleteResponse = await deleteCollection(
        client,
        headers,
        getResponseValue(collectionsPostResponse, "response.id")
    );
    expect(collectionsCollectionsDeleteResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(collectionsCollectionsDeleteResponse, "response.id"), 'deleted collection id').toBe(getResponseValue(collectionsPostResponse, "response.id"));
});
